public class CSVRecord_get_TriageGen0Test {

    /**
     * Since CSVRecord is a final class or has private constructors in many versions,
     * and the provided code snippet implies internal fields 'mapping' and 'values',
     * we use Mockito to simulate the behavior of the internal state.
     */

    @Test
    public void testGet_Success() {
        // Arrange
        CSVRecord record = Mockito.mock(CSVRecord.class);
        String targetName = "column1";
        String expectedValue = "value1";

        // We simulate the logic inside the method: 
        // final Integer index = mapping.get(name);
