public class CSVRecord_get_TriageGen0Test {





    @Test(expected = IllegalArgumentException.class)
    public void testGet_ArrayIndexOutOfBoundsThrowsException() {
        // Arrange
        CSVRecord record = Mockito.mock(CSVRecord.class);
        String name = "errorColumn";

        // Simulate the catch block logic:
        // The index exists in mapping but is out of bounds for the values array.
        when(record.get(name)).thenThrow(new IllegalArgumentException(
                String.format("Index for header '%s' is %d but CSVRecord only has %d values!", name, 1, 1)));

        // Act
        record.get(name);
    }


}

